 'BEST_FIT_SAMPLE': 6,
 'MAX_BLOCKERS': 3,
 'MAX_REPAIRS': 40,
 'PORTFOLIO': [['longest_first', 'shared']],
 'SEED': 1,
 'TIME_MARGIN': 0.035,
