            check(deadline)
            grid.append(["."] * n)

        # A bit represents one grid cell. Union counts shared neighbours once.
        occupied = 0
        neighbours = []
        for r in range(n):
            check(deadline)
            masks = []
            for c in range(n):
                check(deadline)
                mask = 0
                for dr, dc in DIRS:
                    check(deadline)
                    mask |= 1 << (((r + dr) % n) * n + (c + dc) % n)
                masks.append(mask)
            neighbours.append(masks)

        def rank(word, start):
            r, c, dr, dc = start
            overlap = 0
            adjacent = 0
            for letter in word:
                check(deadline)
                cell = grid[r][c]
                if cell == letter:
                    overlap += 1
                elif cell == ".":
                    adjacent |= neighbours[r][c]
                else:
                    return None
                r, c = (r + dr) % n, (c + dc) % n
            if overlap == len(word):
                return None
            touching = (occupied & adjacent).bit_count()
            return placement_rule(overlap), touching, rng.random(), start

        def place(word, r, c, dr, dc):
            nonlocal occupied
            written = []
            for letter in word:
                check(deadline)
                if grid[r][c] == ".":
                    grid[r][c] = letter
                    written.append((r, c))
                r, c = (r + dr) % n, (c + dc) % n
            if has_forbidden(grid, deadline):
                for r, c in written:
                    check(deadline)
                    grid[r][c] = "."
                return False
            for r, c in written:
                check(deadline)
                occupied |= 1 << (r * n + c)
                pos.setdefault(grid[r][c], []).append((r, c))
            return True

        for word in order:
            check(deadline)
            lines = big_string(grid, 2, deadline)
            if word in lines or word[::-1] in lines:
                continue
            ranked = []
            seen = set()
            for k, letter in enumerate(word):
                check(deadline)
                for r, c in pos.get(letter, ()):
                    check(deadline)
                    for dr, dc in DIRS:
                        check(deadline)
                        start = ((r-k*dr) % n, (c-k*dc) % n, dr, dc)
                        if start in seen:
                            continue
                        seen.add(start)
                        entry = rank(word, start)
                        if entry is not None:
                            ranked.append(entry)
            ranked.sort(reverse=True)
            for _, _, _, start in ranked[:CONFIG["TOP_CANDIDATES"]]:
