            for cell, letter in written:
                filled ^= 1 << cell
                cells[cell] = letter if cells[cell] == "." else "."
                for axis, mask in enumerate(cell_masks[cell]):
                    vacant[axis] ^= mask
                    board = letters[axis]
                    board[letter] = board.get(letter,0) ^ mask

        def finish():
            grid = []
            for r in range(n):
