            masks = []
            for c in range(n):
                check(deadline)
                mask = 0
                for dr, dc in DIRS:
                    check(deadline)
                    mask |= 1 << (((r + dr) % n) * n + (c + dc) % n)
                masks.append(mask)
            neighbours.append(masks)

        def rank(word, start):
            r, c, dr, dc = start
            overlap = 0
